import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'https://localhost:7285/api';

export const getStore1CategoryStocks = async () => {
    try {
        console.log('API URL:', `${API_URL}/Store1/CategoryStock`); // Debug için URL'i logla
        const response = await axios.get(`${API_URL}/Store1/CategoryStock`, {
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            }
        });
        console.log('API Response:', response.data); // Debug için yanıtı logla
        return response.data;
    } catch (error) {
        console.error('API Error Details:', {
            message: error.message,
            response: error.response?.data,
            status: error.response?.status
        });
        throw error;
    }
};

export const getStore2CategoryStocks = async () => {
    try {
        console.log('API URL:', `${API_URL}/Store2/CategoryStock`);
        const response = await axios.get(`${API_URL}/Store2/CategoryStock`, {
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            }
        });
        console.log('API Response:', response.data);
        return response.data;
    } catch (error) {
        console.error('API Error Details:', {
            message: error.message,
            response: error.response?.data,
            status: error.response?.status
        });
        throw error;
    }
};

export const getStore3CategoryStocks = async () => {
    try {
        const response = await axios.get(`${API_URL}/Store3/CategoryStock`);
        return response.data;
    } catch (error) {
        console.error('API Error Details:', error);
        throw error;
    }
};

export const createStore3Stock = async (stockData) => {
    try {
        const response = await axios.post(`${API_URL}/Store3/StockCreate`, stockData);
        return response.data;
    } catch (error) {
        console.error('API Error Details:', error);
        throw error;
    }
};

export const createStore3Sale = async (saleData) => {
    try {
        const response = await axios.post(`${API_URL}/Store3/SaleCreate`, saleData);
        return response.data;
    } catch (error) {
        console.error('API Error Details:', error);
        throw error;
    }
};

export const createStore3Return = async (returnData) => {
    try {
        const response = await axios.post(`${API_URL}/Store3/ReturnCreate`, returnData);
        return response.data;
    } catch (error) {
        console.error('API Error Details:', error);
        throw error;
    }
};

export const getStore3AllStocks = async () => {
    try {
        const response = await axios.get(`${API_URL}/Store3/StockGetAll`);
        return response.data;
    } catch (error) {
        console.error('API Error Details:', error);
        throw error;
    }
};
